const { withAppBuildGradle } = require('@expo/config-plugins');

// Signs release builds with the Play upload key. android/ is regenerated by
// `expo prebuild --clean`, so the signing config has to be injected here.
// The keystore path and passwords come from ~/.gradle/gradle.properties
// (BLIPFIELD_UPLOAD_*), never from the repo. Without them, release builds fall back
// to the debug key, which Play rejects, so a missing setup cannot ship.

const SIGNING_CONFIG = `
        release {
            if (project.hasProperty('BLIPFIELD_UPLOAD_STORE_FILE')) {
                storeFile file(BLIPFIELD_UPLOAD_STORE_FILE)
                storePassword BLIPFIELD_UPLOAD_STORE_PASSWORD
                keyAlias BLIPFIELD_UPLOAD_KEY_ALIAS
                keyPassword BLIPFIELD_UPLOAD_KEY_PASSWORD
            }
        }`;

const RELEASE_SIGNING = `if (project.hasProperty('BLIPFIELD_UPLOAD_STORE_FILE')) {
                signingConfig signingConfigs.release
            } else {
                logger.warn('BLIPFIELD_UPLOAD_STORE_FILE is not set: release build is signed with the debug key and Play will reject it.')
                signingConfig signingConfigs.debug
            }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (config) => {
    let gradle = config.modResults.contents;
    if (gradle.includes('BLIPFIELD_UPLOAD_STORE_FILE')) return config;

    const debugConfig = /(signingConfigs \{\s*debug \{[^}]*\})/;
    const releaseSigning = /(release \{[^{}]*?)signingConfig signingConfigs\.debug/;
    if (!debugConfig.test(gradle) || !releaseSigning.test(gradle)) {
      throw new Error('with-release-signing: app/build.gradle layout changed; update the plugin.');
    }

    gradle = gradle.replace(debugConfig, `$1${SIGNING_CONFIG}`);
    gradle = gradle.replace(releaseSigning, `$1${RELEASE_SIGNING}`);
    config.modResults.contents = gradle;
    return config;
  });
};
